_INNER_SRC = zlib.decompress(base64.b85decode(_INNER_SRC_BLOB)).decode()

_inner_ns = {}
exec(compile(_INNER_SRC, "Vj_kc_v24_stranded_fix_isolated", "exec"), _inner_ns)
_inner_agent = [v for v in list(_inner_ns.values()) if callable(v)][-1]

_SAFE = {"farmer": ["PASS"], "hands": [], "market": []}


def agent(observation, configuration=None):
    try:
        out = _inner_agent(observation, configuration)
        if not isinstance(out, dict):
            return dict(_SAFE)
        out.setdefault("farmer", ["PASS"])
        out.setdefault("hands", [])
        out.setdefault("market", [])
        if not isinstance(out["hands"], list):
            out["hands"] = []
        if not isinstance(out["market"], list):
            out["market"] = []
        out["market"] = out["market"][:10]
        return out
    except Exception:
        return dict(_SAFE)
